const body = $input.item.json || {};
const msg = body.message || (body.message_id || body.text || body.caption || body.photo ? body : null);
if (!msg) return [{ json: { routeTo: 'help', chatId: null, message: '👋 Send /generate Product Name | Description with a product photo.' } }];

const chatId = msg.chat?.id?.toString();
const text = msg.text || msg.caption || '';
const photo = msg.photo || null;
const username = msg.from?.username || msg.from?.first_name || body.username || 'Client';
if (!chatId) return [{ json: { routeTo: 'help', chatId: null, message: '❌ Could not determine your chat. Please try again.' } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

if (text && text.trim().toLowerCase() === '/reset') {
  delete staticData.sessions[chatId];
  return [{ json: { routeTo: 'help', chatId, message: '✅ Session reset.\n\nYou can now send /generate again.' } }];
}

const existing = staticData.sessions[chatId];
const THIRTY_MIN = 30 * 60 * 1000;
if (existing && Date.now() - new Date(existing.storedAt || 0).getTime() > THIRTY_MIN) delete staticData.sessions[chatId];

const session = staticData.sessions[chatId];
if (session?.locked) {
  const lockStartedAt = session.lockedAt || session.storedAt || new Date().toISOString();
  const lockAge = Date.now() - new Date(lockStartedAt).getTime();
  const remaining = Math.max(1, Math.ceil((THIRTY_MIN - lockAge) / 60000));
  const job = session.livepeerJob;
  const validJobId = typeof job?.jobId === 'string' && /^mjob_[A-Za-z0-9_-]+$/.test(job.jobId);
  if (validJobId && Date.now() - new Date(job.submittedAt || session.storedAt || 0).getTime() < 60 * 60 * 1000) {
    return [{ json: { routeTo:'resume_livepeer', chatId, username:session.username, productName:session.productName,
      productDescription:session.productDescription, imageUrl:session.imageUrl, script:session.script || '',
      livepeerJobId:job.jobId, pollCount:0, videoStatus:'queued', resuming:true } }];
  }
  // A stale/invalid job ID can happen after a failed test or workflow import.
  // Do not send it to Livepeer's strict get_create_media validator; clear the
  // stale lock and let the current /generate request start a fresh render.
  if (session?.locked && job?.jobId && !validJobId && text && text.trim().toLowerCase().startsWith('/generate')) {
    staticData.sessions[chatId] = { ...session, locked:false, livepeerJob:null };
  } else {
    return [{ json: { routeTo:'locked', chatId, message:`⏳ Already generating "${session.productName}".\n\nWait ~${remaining} min or send /reset` } }];
  }
}

if (!text || !text.toLowerCase().startsWith('/generate')) {
  return [{ json: { routeTo:'help', chatId, message:`👋 Welcome ${username}!\n\nUse:\n/generate Product Name | Description\n\n📸 Attach your product photo to the same message.\n\nExample:\n/generate Nivea Cream | Winter skincare cream` } }];
}
if (!photo || !photo.length) return [{ json: { routeTo:'help', chatId, message:'❌ Missing Photo!\n\nAttach your product photo with the /generate command.' } }];
const photoFileId = photo[photo.length-1].file_id;
const cleaned=text.replace(/^\/generate\s*/i,'').trim();
const parts=cleaned.split('|');
const productName=(parts[0]||'').trim();
const productDescription=(parts[1]||'').trim() || `A premium product called ${productName}`;
if (!productName) return [{ json:{ routeTo:'help', chatId, message:'❌ Missing Product Name!\n\nFormat:\n/generate Product Name | Description' } }];
return [{ json:{ routeTo:'parse_success', chatId, username, productName, productDescription, photoFileId } }];

const input=$input.item;
const binary=input.binary||{};
const prop=Object.keys(binary)[0];
if(!prop) throw new Error('Telegram photo was not downloaded as binary data.');
const buffer=await this.helpers.getBinaryDataBuffer(0, prop);
const mimeType=binary[prop].mimeType||'image/jpeg';
const base=$('Parse Message').item.json;
if(buffer.length>3*1024*1024) throw new Error('Image is larger than Livepeer MCP upload limit (~3 MB).');
return [{json:{...base,livepeerUploadData:buffer.toString('base64'),livepeerMimeType:mimeType}}];

const r=$input.item.json||{};
const base=$('Prepare Livepeer Image Upload').item.json;
function walk(v,k=''){
  if(v==null)return[];
  if(typeof v==='string')return[{k,v}];
  if(Array.isArray(v))return v.flatMap(x=>walk(x,k));
  if(typeof v==='object')return Object.entries(v).flatMap(([a,b])=>walk(b,a));
  return[];
}
const fields=walk(r);
const preferred=fields.find(x=>/^(url|file_url|fileUrl|upload_url|uploadUrl|asset_url|assetUrl|source_url|sourceUrl|public_url|publicUrl)$/i.test(x.k)&&/^https?:\/\//i.test(String(x.v)));
const anyHttp=fields.find(x=>/^https?:\/\//i.test(String(x.v)) && !String(x.v).includes('agent.livepeer.org/get-started') && !String(x.v).includes('docs.the'));
const imageUrl=preferred?.v||anyHttp?.v;
if(!imageUrl) throw new Error('Livepeer upload did not return an accessible https URL. Upload response: '+JSON.stringify(r).slice(0,2500));
return [{json:{...base,imageUrl:String(imageUrl)}}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const data = $input.item.json;
const cutoff = Date.now() - 30 * 60 * 1000;
for (const [id, s] of Object.entries(staticData.sessions)) {
  if (new Date(s.storedAt || 0).getTime() < cutoff) delete staticData.sessions[id];
}
const now = new Date().toISOString();
staticData.sessions[data.chatId] = {
  chatId:data.chatId, username:data.username, productName:data.productName,
  productDescription:data.productDescription, imageUrl:data.imageUrl,
  storedAt:now, locked:true, lockedAt:now
};
return [{ json:data }];

const scriptNode=$input.item.json;
const script=scriptNode.content?.filter?.(p=>p.type==='text').map(p=>p.text).join('\n') || scriptNode.message?.content || scriptNode.choices?.[0]?.message?.content || scriptNode.text || '';
if (!script || script.trim().length<10) throw new Error('Claude returned empty script.');
const base=$('Parse Message').item.json;
return [{json:{chatId:base.chatId, productName:base.productName, productDescription:base.productDescription,
  imageUrl:$('Extract Livepeer Upload URL').item.json.imageUrl, username:base.username, script:script.trim()}}];

