const r = $input.item.json ?? {};
const base = $('Extract Script').item.json;

function walk(v) {
  if (v == null) return [];
  if (typeof v === 'string') return [v];
  if (Array.isArray(v)) return v.flatMap(walk);
  if (typeof v === 'object') return Object.values(v).flatMap(walk);
  return [];
}

const structured = r.structuredContent ?? {};
const directCandidates = [
  structured.url,
  r.url,
  r.output?.url,
  r.result?.url,
];

let videoUrl = directCandidates.find(v =>
  typeof v === 'string' &&
  /^https?:\/\//i.test(v) &&
  /\.mp4(?:\?.*)?$/i.test(v)
);

if (!videoUrl) {
  videoUrl = walk(r).find(v =>
    /^https?:\/\//i.test(v) &&
    /\.mp4(?:\?.*)?$/i.test(v)
  );
}

if (!videoUrl) {
  throw new Error(
    'Livepeer run_capability returned no MP4 URL. Raw response: ' +
    JSON.stringify(r).slice(0, 5000)
  );
}

const cost = structured['cost_usd_estimated'] ?? structured['costUsdEstimated'] ?? null;
const units = structured['cost_units'] ?? structured['costUnits'] ?? null;
const capability = structured.capability ?? structured.requested_capability ?? null;

return [{
  json: {
    chatId: base.chatId,
    productName: base.productName,
    productDescription: base.productDescription,
    username: base.username,
    script: base.script,
    imageUrl: base.imageUrl,
    videoUrl,
    videoStatus: 'completed',
    livepeerCapability: capability,
    livepeerEstimatedCostUsd: cost,
    livepeerCostUnits: units,
    livepeerRunResponse: r
  }
}];
